from __future__ import annotations
import math


class Group:
    def __init__(self, members: list[str]) -> None:
        self._members = list(members)
        self._member_set = set(members)
        # Store balances in integer cents to avoid floating-point issues
        self._balances: dict[str, int] = {m: 0 for m in self._members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be positive.")

        if payer not in self._member_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            parts = list(self._members)
        else:
            parts = list(participants)

        if not parts:
            raise ValueError("Participants list cannot be empty.")

        for p in parts:
            if p not in self._member_set:
                raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        n = len(parts)

        # Requirement 4:
        # Every other participant owes exactly the amount rounded down to the cent.
        # Leftover cents are borne by the payer.
        base_split = total_cents // n

        self._balances[payer] += total_cents

        if payer in parts:
            # Other participants pay base_split each
            # Payer pays the rest: total_cents - base_split * (n - 1)
            other_count = n - 1
            for p in parts:
                if p != payer:
                    self._balances[p] -= base_split
            payer_share = total_cents - (base_split * other_count)
            self._balances[payer] -= payer_share
        else:
            # Payer is not in participants: all n participants are "other"
            for p in parts:
                self._balances[p] -= base_split
            # Leftover cents are borne by the payer:
            leftover = total_cents - (base_split * n)
            self._balances[payer] -= leftover

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self._members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors (net negative) and Creditors (net positive)
        debtors: list[list] = []
        creditors: list[list] = []

        for m in self._members:
            bal = self._balances[m]
            if bal < 0:
                debtors.append([m, -bal])
            elif bal > 0:
                creditors.append([m, bal])

        payments: list[tuple[str, str, float]] = []

        d_idx = 0
        c_idx = 0

        # Greedy match: standard algorithm guarantees at most (|debtors| + |creditors| - 1)
        # which is at most (number of members - 1) payments.
        while d_idx < len(debtors) and c_idx < len(creditors):
            d_name, d_amt = debtors[d_idx]
            c_name, c_amt = creditors[c_idx]

            transfer = min(d_amt, c_amt)

            # Requirement 2: Never propose a payment smaller than 1.00 (100 cents).
            # Debts below 1.00 are written off.
            if transfer >= 100:
                payments.append((d_name, c_name, transfer / 100.0))

            debtors[d_idx][1] -= transfer
            creditors[c_idx][1] -= transfer

            if debtors[d_idx][1] == 0:
                d_idx += 1
            if creditors[c_idx][1] == 0:
                c_idx += 1

        return payments
